  "@scope ([data-astryx-theme=\"neutral\"]) to ([data-astryx-theme]) {",
  "  :where(h1, h2, h3, h4, h5, h6) {",
  "    font-family: var(--font-family-heading);",
  "    color: var(--color-text-primary);",
  "  }",
  "",
  "  :where(h1) {",
  "    font-size: var(--text-heading-1-size);",
  "    font-weight: var(--text-heading-1-weight);",
  "    line-height: var(--text-heading-1-leading);",
  "  }",
  "",
  "  :where(h2) {",
  "    font-size: var(--text-heading-2-size);",
  "    font-weight: var(--text-heading-2-weight);",
  "    line-height: var(--text-heading-2-leading);",
  "  }",
  "",
  "  :where(h3) {",
  "    font-size: var(--text-heading-3-size);",
  "    font-weight: var(--text-heading-3-weight);",
  "    line-height: var(--text-heading-3-leading);",
  "  }",
  "",
  "  :where(h4) {",
  "    font-size: var(--text-heading-4-size);",
  "    font-weight: var(--text-heading-4-weight);",
  "    line-height: var(--text-heading-4-leading);",
  "  }",
  "",
  "  :where(h5) {",
  "    font-size: var(--text-heading-5-size);",
  "    font-weight: var(--text-heading-5-weight);",
  "    line-height: var(--text-heading-5-leading);",
  "  }",
  "",
  "  :where(h6) {",
  "    font-size: var(--text-heading-6-size);",
  "    font-weight: var(--text-heading-6-weight);",
  "    line-height: var(--text-heading-6-leading);",
  "  }",
  "",
  "  :where(p) {",
  "    font-family: var(--font-family-body);",
  "    font-size: var(--text-body-size);",
  "    font-weight: var(--text-body-weight);",
  "    line-height: var(--text-body-leading);",
  "    color: var(--color-text-primary);",
  "  }",
  "",
  "  :where(small) {",
  "    font-size: var(--text-supporting-size);",
  "    font-weight: var(--text-supporting-weight);",
  "    line-height: var(--text-supporting-leading);",
  "    color: var(--color-text-secondary);",
  "  }",
  "",
  "  :where(code, pre) {",
  "    font-family: var(--font-family-code);",
  "    font-size: var(--text-code-size);",
  "    line-height: var(--text-code-leading);",
  "  }",
  "",
  "  :where(hr) {",
  "    border: none;",
  "    border-top: 1px solid var(--color-border);",
  "  }",
  "}",
  "}",
  "",
  "@layer astryx-theme {",
  "  html[data-theme=\"light\"] { color-scheme: light; }",
  "  html[data-theme=\"dark\"] { color-scheme: dark; }",
  "",
  "@scope ([data-astryx-theme=\"neutral\"]) to ([data-astryx-theme]) {",
  "  :scope {",
  "    --_scaled-font-size-4xs: min(calc(0.375rem * var(--_dynamic-type-caption2, 1)), var(--_scaled-font-size-3xs));",
  "    --font-size-4xs: var(--_scaled-font-size-4xs);",
  "    --_scaled-font-size-3xs: min(calc(0.4375rem * var(--_dynamic-type-caption2, 1)), var(--_scaled-font-size-2xs));",
  "    --font-size-3xs: var(--_scaled-font-size-3xs);",
  "    --_scaled-font-size-2xs: min(calc(0.5rem * var(--_dynamic-type-caption2, 1)), var(--_scaled-font-size-xs));",
  "    --font-size-2xs: var(--_scaled-font-size-2xs);",
  "    --_scaled-font-size-xs: min(calc(0.625rem * var(--_dynamic-type-caption1, 1)), var(--_scaled-font-size-sm));",
  "    --font-size-xs: var(--_scaled-font-size-xs);",
  "    --_scaled-font-size-sm: min(calc(0.75rem * var(--_dynamic-type-footnote, 1)), var(--_scaled-font-size-base));",
  "    --font-size-sm: var(--_scaled-font-size-sm);",
  "    --_scaled-font-size-base: min(calc(0.875rem * var(--_dynamic-type-body, 1)), var(--_scaled-font-size-lg));",
  "    --font-size-base: var(--_scaled-font-size-base);",
  "    --_scaled-font-size-lg: min(calc(1.0625rem * var(--_dynamic-type-title3, 1)), var(--_scaled-font-size-xl));",
  "    --font-size-lg: var(--_scaled-font-size-lg);",
  "    --_scaled-font-size-xl: min(calc(1.25rem * var(--_dynamic-type-title2, 1)), var(--_scaled-font-size-2xl));",
  "    --font-size-xl: var(--_scaled-font-size-xl);",
  "    --_scaled-font-size-2xl: min(calc(1.5rem * var(--_dynamic-type-title1, 1)), var(--_scaled-font-size-3xl));",
  "    --font-size-2xl: var(--_scaled-font-size-2xl);",
  "    --_scaled-font-size-3xl: min(calc(1.8125rem * var(--_dynamic-type-title1, 1)), var(--_scaled-font-size-4xl));",
  "    --font-size-3xl: var(--_scaled-font-size-3xl);",
  "    --_scaled-font-size-4xl: min(calc(2.1875rem * var(--_dynamic-type-large-title, 1)), var(--_scaled-font-size-5xl));",
  "    --font-size-4xl: var(--_scaled-font-size-4xl);",
  "    --_scaled-font-size-5xl: calc(2.625rem * var(--_dynamic-type-large-title, 1));",
  "    --font-size-5xl: var(--_scaled-font-size-5xl);",
  "    --text-heading-1-size: var(--font-size-2xl);",
  "    --text-heading-1-weight: var(--font-weight-semibold);",
  "    --text-heading-1-leading: 1.3333;",
  "    --text-heading-2-size: var(--font-size-xl);",
  "    --text-heading-2-weight: var(--font-weight-semibold);",
  "    --text-heading-2-leading: 1.4;",
  "    --text-heading-3-size: var(--font-size-lg);",
  "    --text-heading-3-weight: var(--font-weight-bold);",
  "    --text-heading-3-leading: 1.4118;",
  "    --text-heading-4-size: var(--font-size-base);",
  "    --text-heading-4-weight: var(--font-weight-bold);",
  "    --text-heading-4-leading: 1.4286;",
  "    --text-heading-5-size: var(--font-size-sm);",
  "    --text-heading-5-weight: var(--font-weight-semibold);",
  "    --text-heading-5-leading: 1.6667;",
  "    --text-heading-6-size: var(--font-size-xs);",
  "    --text-heading-6-weight: var(--font-weight-semibold);",
  "    --text-heading-6-leading: 1.6;",
  "    --text-body-size: var(--font-size-base);",
  "    --text-body-weight: var(--font-weight-normal);",
  "    --text-body-leading: 1.4286;",
  "    --text-large-size: var(--font-size-lg);",
  "    --text-large-weight: var(--font-weight-semibold);",
  "    --text-large-leading: 1.4118;",
  "    --text-label-size: var(--font-size-base);",
  "    --text-label-weight: var(--font-weight-medium);",
  "    --text-label-leading: 1.4286;",
  "    --text-code-size: var(--font-size-base);",
  "    --text-code-weight: var(--font-weight-normal);",
  "    --text-code-leading: 1.4286;",
  "    --text-supporting-size: var(--font-size-sm);",
  "    --text-supporting-weight: var(--font-weight-normal);",
  "    --text-supporting-leading: 1.6667;",
  "    --text-display-1-size: var(--font-size-5xl);",
  "    --text-display-1-weight: var(--font-weight-normal);",
  "    --text-display-1-leading: 1.2381;",
  "    --text-display-2-size: var(--font-size-4xl);",
  "    --text-display-2-weight: var(--font-weight-normal);",
  "    --text-display-2-leading: 1.2571;",
  "    --text-display-3-size: var(--font-size-3xl);",
  "    --text-display-3-weight: var(--font-weight-normal);",
  "    --text-display-3-leading: 1.3793;",
  "    --duration-fast-min: 95ms;",
  "    --duration-fast: 125ms;",
  "    --duration-fast-max: 165ms;",
  "    --duration-medium-min: 225ms;",
  "    --duration-medium: 300ms;",
  "    --duration-medium-max: 400ms;",
  "    --duration-slow-min: 525ms;",
  "    --duration-slow: 700ms;",
  "    --duration-slow-max: 935ms;",
  "    --_astryx-pre-tempo-duration-fast-min: 95ms;",
  "    --_astryx-pre-tempo-duration-fast: 125ms;",
  "    --_astryx-pre-tempo-duration-fast-max: 165ms;",
  "    --_astryx-pre-tempo-duration-medium-min: 225ms;",
  "    --_astryx-pre-tempo-duration-medium: 300ms;",
